TE TABLE public.quickshift_EasyEcom_FACT_ITEMS AS WITH orders AS ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY CAST(order_id AS BIGINT), CAST(invoice_id AS BIGINT) ORDER BY last_update_date DESC) AS rw FROM public.Easyecom_quickshift_customer_orders_v2 c ) a WHERE rw = 1 ), first_order AS ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY order_date ASC) AS rw FROM public.Easyecom_quickshift_customer_orders_v2 c ) a WHERE rw = 1 ) SELECT s.pincode, UPPER(s.Marketplace) AS SHOP_NAME, s.carrier_id, UPPER(s.courier) AS courier, UPPER(s.customer_name) AS customer_name, s.email, s.contact_num, UPPER(s.MARKETPLACE) AS marketplace, s.MARKETPLACE_ID, s.ORDER_ID, s.suborder_id, s.invoice_id, s.reference_code, s.Marketplace_LineItem_ID, s.invoice_date, CAST(s.manifest_date AS TIMESTAMP) AS manifest_Date, CAST(s.shipping_last_update_date AS TIMESTAMP) AS shipping_last_update_date, CAST(CASE WHEN LOWER(s.shipping_status) = \'delivered\' THEN CAST(s.shipping_last_update_date AS TIMESTAMP) END AS TIMESTAMP) AS Delivered_Date, UPPER(s.shipping_status) AS shipping_status, s.awb, s.SKU, s.master_sku, UPPER(s.sku_type) AS sku_type, s.PRODUCT_ID, UPPER(s.PRODUCTNAME) AS PRODUCTNAME, s.CURRENCY, s.IS_REFUND, UPPER(COALESCE(s.city)) AS City, UPPER(COALESCE(s.state)) AS State, UPPER(s.order_Status) AS order_Status, s.ORDER_Date, s.SHIPPING_PRICE, s.number_of_products_in_combo, s.suborder_quantity, s.shipped_quantity, s.returned_quantity, s.cancelled_quantity, s.return_sales, s.cancel_sales, s.Tax, s.suborder_mrp, UPPER(s.category) AS category, s.discount, s.selling_price, COALESCE(s.suborder_mrp, 0) * s.suborder_quantity AS mrp_sales, CASE WHEN ((COALESCE(s.suborder_mrp, 0) * s.suborder_quantity) IS NULL OR (COALESCE(s.suborder_mrp, 0) * s.suborder_quantity) < s.selling_price) THEN s.discount ELSE (COALESCE(s.suborder_mrp, 0) * s.suborder_quantity) - s.selling_price END AS Discount_MRP, s.new_customer_flag, s.new_customer_flag_month, UPPER(s.Warehouse_name) AS Warehouse_name, s.Days_in_Shipment, UPPER(s.Channel) AS Channel, UPPER(s.Payment_mode) AS Payment_mode, s.import_date, s.last_update_date, s.pickup_pincode, null picked_up_time, null intransit_time, null delivered_time, UPPER(fsm.product_name) AS mapped_product_name, UPPER(fsm.category) AS mapped_Category, upper(fsm.commonsku) as commonsku FROM ( SELECT o.PIN_CODE AS pincode, o.MARKETPLACE AS SHOP_NAME, o.carrier_id, o.courier, o.customer_name, o.email, o.contact_num, o.MARKETPLACE, o.MARKETPLACE_ID, CAST(CAST(o.ORDER_ID AS BIGINT) AS VARCHAR) AS ORDER_ID, s.suborder_id::VARCHAR AS suborder_id, CAST(CAST(o.invoice_id AS BIGINT) AS VARCHAR) AS invoice_id, o.reference_code, CAST(o.INVOICE_DATE AS TIMESTAMP) AS INVOICE_DATE, o.manifest_date, o.shipping_Last_update_date AS shipping_last_update_date, o.shipping_status, o.awb_number AS awb, s.marketplace_sku::VARCHAR AS sku, s.sku::VARCHAR AS master_sku, s.sku_type::VARCHAR AS sku_type, s.product_id::VARCHAR AS product_id, s.suborder_num::VARCHAR AS marketplace_lineitem_id, s.productName::VARCHAR AS productname, CASE WHEN o.pickup_country = \'India\' THEN \'INR\' END AS CURRENCY, CASE WHEN CAST(s.returned_quantity::VARCHAR AS BIGINT) > 0 THEN 1 ELSE 0 END AS IS_REFUND, UPPER(CAST(o.CITY AS VARCHAR)) AS City, UPPER(CAST(o.STATE AS VARCHAR)) AS State, o.order_status, o.ORDER_Date, COALESCE(CAST(REPLACE(s.total_shipping_charge::VARCHAR, \',\', \'\') AS DOUBLE PRECISION), 0) AS shipping_price, CAST(s.item_quantity::VARCHAR AS BIGINT) AS number_of_products_in_combo, CAST(s.suborder_quantity::VARCHAR AS BIGINT) AS suborder_quantity, CAST(s.shipped_quantity::VARCHAR AS BIGINT) AS shipped_quantity, CAST(s.returned_quantity::VARCHAR AS BIGINT) AS returned_quantity, CAST(s.cancelled_quantity::VARCHAR AS BIGINT) AS cancelled_quantity, CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN 0 ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END AS selling_price, CASE WHEN CAST(s.returned_quantity::VARCHAR AS BIGINT) > 0 THEN (CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN 0 ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) * (CAST(s.returned_quantity::VARCHAR AS BIGINT)) / (CAST(s.item_quantity::VARCHAR AS BIGINT)) END AS return_sales, CASE WHEN CAST(s.cancelled_quantity::VARCHAR AS BIGINT) > 0 THEN (CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN 0 ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) END AS cancel_sales, COALESCE(CAST(s.TAX::VARCHAR AS DOUBLE PRECISION), 0) AS Tax, CAST(REPLACE(s.mrp::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) AS suborder_mrp, s.category::VARCHAR AS category, -1 * (COALESCE(CAST(o.total_discount AS DOUBLE PRECISION) * (CASE WHEN (CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN CAST(REPLACE(s.mrp::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) = 0 THEN 1 ELSE (CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN CAST(REPLACE(s.mrp::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) END / CASE WHEN SUM(CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN CAST(REPLACE(s.mrp::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) OVER (PARTITION BY CAST(o.order_id AS BIGINT)) = 0 THEN 1 ELSE SUM(CASE WHEN CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) IS NULL THEN CAST(REPLACE(s.mrp::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) ELSE CAST(REPLACE(s.selling_price::VARCHAR, \',\', \'\') AS DOUBLE PRECISION) END) OVER (PARTITION BY CAST(o.order_id AS BIGINT)) END), 0)) AS discount, CASE WHEN fo.order_id = o.order_id THEN \'New\' ELSE \'Repeat\' END AS new_customer_flag, CASE WHEN DATE_TRUNC(\'month\', CAST(LEFT(fo.order_date, 10) AS DATE)) = DATE_TRUNC(\'month\', CAST(LEFT(o.order_date, 10) AS DATE)) THEN \'New\' ELSE \'Repeat\' END AS new_customer_flag_month, o.company_name AS Warehouse_Name, CAST(CASE WHEN o.shipping_STATUS IN (\'In Transit\', \'Shipment Created\') THEN DATEDIFF(day, CAST(LEFT(o.ORDER_Date, 10) AS DATE), CURRENT_DATE) WHEN o.shipping_STATUS IN (\'Delivered\', \'Delivered To Origin\') THEN DATEDIFF(day, CAST(LEFT(o.ORDER_Date, 10) AS DATE), CAST(LEFT(o.shipping_Last_update_date, 10) AS DATE)) END AS BIGINT) AS Days_in_Shipment, o.marketplace AS Channel, o.payment_mode, o.import_date, o.last_update_date, o.pickup_pin_code AS pickup_pincode, ROW_NUMBER() OVER (PARTITION BY s.suborder_id::VARCHAR ORDER BY o.last_update_date DESC) AS rw FROM orders o LEFT JOIN first_order fo ON fo.contact_num = o.contact_num, o.suborders s ) s left join (select * from (select product_name , upper(CAST(sku AS VARCHAR)) AS commonsku , upper(category_name) as category , ROW_NUMBER() OVER (PARTITION BY REPLACE(upper(CAST(sku AS VARCHAR)), \' \', \'\') ORDER BY LENGTH(COALESCE(upper(CAST(sku AS VARCHAR)), \'\')) DESC) AS rw FROM public.EasyEcom_quickshift_easyecom_product_master ) WHERE rw = 1 ) fsm ON LOWER(REPLACE(CAST(s.master_sku AS VARCHAR), \' \', \'\')) = LOWER(REPLACE(CAST(fsm.commonsku AS VARCHAR), \' \', \'\')) WHERE s.rw = 1;",
                    "transaction": true
                }
            ) }}
